<?php
namespace AutoDealership\Core {final class ProductSetup {public static function t($ar,$en){return $en;}}}
namespace {
define('ABSPATH',__DIR__);$options=array();function get_option($key,$fallback=false){global $options;return $options[$key]??$fallback;}function update_option($key,$value,$autoload=null){global $options;$options[$key]=$value;}function sanitize_text_field($value){return strip_tags($value);}class WP_Error {function __construct(...$args){}}function is_wp_error($value){return $value instanceof WP_Error;}
require dirname(__DIR__).'/src/Core/BrandPalette.php';require dirname(__DIR__).'/src/Core/BrandColorLibrary.php';use AutoDealership\Core\BrandPalette as Palette;use AutoDealership\Core\BrandColorLibrary as Library;
function check($value,$label){if(!$value){throw new \RuntimeException($label);}echo "PASS $label\n";}
$meta=Library::empty_meta();check(!is_wp_error(Library::meta($meta)),'empty metadata accepted');$meta['generated']['light']['action']='#abcdef';check(Library::meta($meta)['generated']['light']['action']==='#ABCDEF','generated colors normalized');$bad=$meta;$bad['generated']['light']['unknown']='#000000';check(is_wp_error(Library::meta($bad)),'unknown generated token rejected');$bad=$meta;$bad['roles']['primary']='javascript:alert(1)';check(is_wp_error(Library::meta($bad)),'unsafe role rejected');
$scheme=$meta;$scheme['style']='luxury';check(Library::meta($scheme)['style']==='luxury','selected scheme survives normalization');$scheme['style']='not-a-scheme';check(is_wp_error(Library::meta($scheme)),'unknown selected scheme rejected');
foreach(array('complementary','split','triadic') as $style){$scheme=$meta;$scheme['style']=$style;check(Library::meta($scheme)['style']===$style,'new harmonious scheme accepted: '.$style);}
$entry=array('name'=>'هوية عربية','palette'=>Palette::empty_config(),'meta'=>$meta);check(!is_wp_error(Library::library(array('identity_test'=>$entry))),'Arabic named identity accepted');$bad=$entry;$bad['palette']['light']['action']='red';check(is_wp_error(Library::library(array('test'=>$bad))),'invalid saved palette rejected');check(is_wp_error(Library::library(array_fill(0,13,$entry))),'library bound enforced');$bad=$entry;$bad['name']=str_repeat('ع',81);check(is_wp_error(Library::library(array('test'=>$bad))),'long Arabic identity name rejected');
for($i=0;$i<25;$i++){Library::remember(Palette::empty_config(),array('format'=>1,'light'=>array('action'=>sprintf('#%06X',$i)),'dark'=>array()));}check(count($options['adc_brand_palette_history'])===20,'history is bounded to 20 revisions');check($options['adc_brand_palette_history'][0]['palette']===Palette::empty_config(),'history stores original palette without mutating it');
